package android.content;import java.util.*;public class Intent{public static final String ACTION_VIEW="view";public static final int FLAG_ACTIVITY_NEW_TASK=0x10000000;public android.net.Uri uri;public String component;public int flags;public Map<String,Object> extras=new HashMap<>();public Intent(String a,android.net.Uri u){uri=u;}public Intent setClassName(Context c,String n){component=n;return this;}public Intent addFlags(int f){flags|=f;return this;}public Intent putExtra(String k,boolean v){extras.put(k,v);return this;}public Intent putExtra(String k,int v){extras.put(k,v);return this;}}
